import { buildSchema, graphql } from "graphql";
const schema = buildSchema("type Book { title: String!, pages: Int! } type Query { book: Book! }");

const rootValue = { book: () => ({ title: "Moon Trip", pages: 24 }) };
const result = await graphql({ schema, rootValue, source: "{ book { title } }", variableValues: {} });
console.log(JSON.stringify(result.data));
